contract:
{
  "interface": {
    "mode": "stdin_stdout",
    "signature": "stdin -> stdout",
    "input_channel": "stdin",
    "output_channel": "stdout"
  },
  "preconditions": [
    {
      "id": "P1",
      "expression": "int(q) >= 1 and int(q) <= 100000",
      "description": "The number of operations q is an integer between 1 and 10^5 inclusive."
    },
    {
      "id": "P2",
      "expression": "all(len(line.strip()) > 0 for line in stdin_lines[1:])",
      "description": "Each of the q operation lines is non-empty."
    },
    {
      "id": "P3",
      "expression": "all(op_type in ['set', 'remove', 'query', 'undo'] for op_type in [line.split()[0] for line in stdin_lines[1:]])",
      "description": "Every operation type is one of the four allowed commands."
    },
    {
      "id": "P4",
      "expression": "all(1 <= len(name) <= 15 and name.islower() and name.isalpha() for line in stdin_lines[1:] for name in [line.split()[1]] if line.split()[0] in ['set', 'remove', 'query'])",
      "description": "Assignment names consist only of lowercase English letters and have length between 1 and 15."
    },
    {
      "id": "P5",
      "expression": "all(1 <= int(priority) <= 10**9 for line in stdin_lines[1:] if line.split()[0] == 'set' for priority in [line.split()[2]])",
      "description": "For set operations, the priority xi is an integer between 1 and 10^9."
    },
    {
      "id": "P6",
      "expression": "all(0 <= int(days) < i for i, line in enumerate(stdin_lines[1:], start=1) if line.split()[0] == 'undo' for days in [line.split()[1]])",
      "description": "For undo operations, di is an integer such that 0 <= di < current day index i."
    },
    {
      "id": "P7",
      "expression": "stdin_lines[-1].split()[0] == 'query'",
      "description": "The last operation in the input is guaranteed to be a query."
    }
  ],
  "postconditions": [
    {
      "id": "Q1",
      "expression": "len(stdout_lines) == sum(1 for line in stdin_lines[1:] if line.split()[0] == 'query')",
      "description": "The number of output lines equals the number of query operations in the input."
    },
    {
      "id": "Q2",
      "expression": "all(int(out_val) == -1 or int(out_val) >= 0 for out_val in stdout_lines)",
      "description": "Each output line is an integer, either -1 or a non-negative count."
    },
    {
      "id": "Q3",
      "expression": "all((int(stdout_lines[k]) == -1) == (query_name not in state_at_query[k]) for k, query_name in enumerate(query_sequence))",
      "description": "For each query k, the output is -1 if and only if the queried assignment is not present in the to-do list at that moment."
    },
    {
      "id": "Q4",
      "expression": "all(int(stdout_lines[k]) == sum(1 for name, prio in state_at_query[k].items() if prio < state_at_query[k][query_name]) for k, query_name in enumerate(query_sequence) if query_name in state_at_query[k])",
      "description": "For each query k where the assignment exists, the output equals the count of assignments in the current list with a strictly smaller priority value."
    },
    {
      "id": "Q5",
      "expression": "all(state_at_query[k] == state_after_undo[k] for k in range(len(query_sequence)))",
      "description": "The state used for each query reflects all prior operations including the effects of any undo commands executed before that query."
    }
  ],
  "invariants
